import * as THREE from 'three/webgpu';
import { Fn, uv, vec2, vec3, vec4, float, uniform, smoothstep, abs, max, length, mix, texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'badge-pricing';
  group.position.set(1.25, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.1;
  const height = 0.42;
  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const inkColor = uniform(vec3(0x16 / 255, 0x16 / 255, 0x1d / 255));
  const paperColor = uniform(vec3(0xe8 / 255, 0xec / 255, 0xf2 / 255));
  const accentColor = uniform(vec3(1.0, 0x2a / 255, 0x38 / 255));
  const hoverAmount = uniform(0.0);
  const focusAmount = uniform(0.0);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const uvNode = uv();

  const colorNode = Fn(() => {
    const p = uvNode.sub(vec2(0.5, 0.5)).mul(vec2(width, height));
    const halfW = float(width / 2 - height / 2);
    const halfH = float(height / 2);

    const dx = max(abs(p.x).sub(halfW), 0.0);
    const dist = length(vec2(dx, p.y)).sub(halfH);

    const edgeWidth = float(0.012);
    const capsuleMask = smoothstep(edgeWidth, edgeWidth * -1.0, dist);

    const grain = texture(map, uvNode).r.mul(0.08);

    const base = mix(inkColor, inkColor.add(vec3(grain, grain, grain)), 0.5);

    const edgeGlow = smoothstep(edgeWidth, -0.02, abs(dist)).mul(
      accentColor.mul(float(0.6).add(focusAmount.mul(0.8)).add(hoverAmount.mul(0.2)))
    );

    const rimGlow = smoothstep(0.0, -0.03, dist).mul(
      smoothstep(-0.03, 0.0, dist.add(0.01))
    );

    const finalColor = base.add(edgeGlow).add(paperColor.mul(rimGlow).mul(0.05));

    return vec4(finalColor, capsuleMask);
  })();

  material.colorNode = colorNode;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'badge-pricing-mesh';
  group.add(mesh);

  // interactive state
  let hoverTl = null;
  let pressTl = null;
  const baseY = group.position.y;

  const onHoverIn = () => {
    hoverTl && hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(hoverAmount, { value: 1.0, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onHoverOut = () => {
    hoverTl && hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTl.to(hoverAmount, { value: 0.0, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onClick = () => {
    pressTl && pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });
    pressTl.to(focusAmount, { value: 1.0, duration: 0.12, ease: 'back.out' }, 0);

    if (ctx.emit) {
      ctx.emit('hub-pricing.select');
    } else if (group.userData.emit) {
      group.userData.emit('hub-pricing.select');
    }
  };

  group.userData.handlers = {
    pointerover: onHoverIn,
    pointerenter: onHoverIn,
    pointerout: onHoverOut,
    pointerleave: onHoverOut,
    click: onClick,
    pointerdown: () => {
      focusAmount.value = 1.0;
    },
    pointerup: () => {
      focusAmount.value = 0.0;
    },
  };

  group.userData.cleanup = () => {
    hoverTl && hoverTl.kill();
    pressTl && pressTl.kill();
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
